SELECT SUM(analytics_order_facts.net_revenue) / CAST(NULLIF(COUNT(DISTINCT analytics_order_facts.order_id), 0) AS DECIMAL) AS average_order_value FROM analytics_order_facts WHERE analytics_order_facts.year = 2024 AND analytics_order_facts.month = 5 AND analytics_order_facts.region = 'South' AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'mid_market' LIMIT 1000
